package in.carenest.clinic.api;
import in.carenest.clinic.security.SecurityConfig.TenantPrincipal; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.dao.DuplicateKeyException; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
@RestController @RequestMapping("/api") public class QueueApi {
 private final JdbcTemplate db; private final Map<String,Deque<Instant>> publicAttempts=new ConcurrentHashMap<>(); public QueueApi(JdbcTemplate db){this.db=db;}
 public record Registration(@NotBlank String name,@Pattern(regexp="[0-9+ -]{8,20}") String mobile,@Min(0) @Max(130) Integer age,BigDecimal weightKg,String bp,String sugar){}
 @GetMapping("/queue") public Map<String,Object> queue(@AuthenticationPrincipal TenantPrincipal p){tenant(p);LocalDate day=LocalDate.now();var rows=db.queryForList("select id,token_number,patient_name,mobile,age,weight_kg,bp,sugar,status,started_at,completed_at,created_at,(select count(*) from patient_documents d where d.queue_entry_id=q.id) documents from queue_entries q where clinic_id=? and branch_id=? and queue_date=? order by token_number",p.clinicId(),p.branchId(),day);var config=db.queryForMap("select b.queue_paused,b.current_token,c.average_visit_minutes,c.sms_enabled,c.whatsapp_enabled from branches b join clinics c on c.id=b.clinic_id where b.id=? and b.clinic_id=?",p.branchId(),p.clinicId());long waiting=rows.stream().filter(r->"WAITING".equals(r.get("status"))).count();Map<String,Object> out=new LinkedHashMap<>(config);out.put("businessDate",day);out.put("waiting",waiting);out.put("total",rows.size());out.put("patients",rows);return out;}
 @PostMapping("/queue") @Transactional @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(@AuthenticationPrincipal TenantPrincipal p,@Valid @RequestBody Registration x){tenant(p);return add(p.clinicId(),p.branchId(),p.userId(),x);}
 @GetMapping("/public/queue/{identifier}") public Map<String,Object> publicClinicDashboard(@PathVariable String identifier){var c=publicClinic(identifier);UUID clinic=(UUID)c.get("clinic_id"),branch=(UUID)c.get("branch_id");BranchClock clock=branchClock(branch);SessionWindow session=clinicSession(clinic,branch,clock.time());Map<String,Object> out=new LinkedHashMap<>(c);out.put("businessDate",clock.date());out.put("currentSession",session.code());out.putAll(db.queryForMap("select count(*) total_today,count(*) filter(where status='WAITING') waiting_now,coalesce((select current_token from daily_queue_counters where branch_id=? and counter_date=?),0) current_token from queue_entries where clinic_id=? and branch_id=? and queue_date=?",branch,clock.date(),clinic,branch,clock.date()));return out;}
 @PostMapping("/public/queue/{identifier}") @Transactional @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> publicRegister(@PathVariable String identifier,@Valid @RequestBody Registration x,HttpServletRequest request){var c=publicClinic(identifier);UUID clinic=(UUID)c.get("clinic_id");limitPublicRegistration(clinic,clientIp(request));return add(clinic,(UUID)c.get("branch_id"),null,x);}
 @GetMapping("/public/queue/{slug}/{trackingToken}") public Map<String,Object> publicStatus(@PathVariable String slug,@PathVariable UUID trackingToken){var row=db.queryForMap("""
   select q.id,q.patient_name,q.token_number,q.queue_period,q.status,q.created_at,c.name clinic_name,c.theme,
     b.current_token,b.queue_paused,c.average_visit_minutes,
     (select count(*) from queue_entries ahead where ahead.branch_id=q.branch_id and ahead.queue_date=q.queue_date and ahead.queue_period=q.queue_period and ahead.status='WAITING' and ahead.token_number<q.token_number) people_ahead
   from queue_entries q join clinics c on c.id=q.clinic_id join branches b on b.id=q.branch_id
   where c.slug=? and q.tracking_token=? and q.queue_date=current_date
   """,slug,trackingToken);long ahead=((Number)row.get("people_ahead")).longValue();int average=((Number)row.get("average_visit_minutes")).intValue();row.put("estimatedWaitMinutes",ahead*average);return row;}
 private Map<String,Object> add(UUID clinic,UUID branch,UUID actor,Registration x){BranchClock clock=branchClock(branch);SessionWindow session=clinicSession(clinic,branch,clock.time());String period=session.code();String mobile=x.mobile().replaceAll("[ -]","");db.query("select pg_advisory_xact_lock(hashtextextended(?,0))",ps->ps.setString(1,branch+"|"+clock.date()+"|"+period),rs->{});Integer token=db.queryForObject("insert into daily_queue_counters(clinic_id,branch_id,counter_date,last_issued_token) values(?,?,?,1) on conflict(branch_id,counter_date) do update set last_issued_token=daily_queue_counters.last_issued_token+1,updated_at=now() returning last_issued_token",Integer.class,clinic,branch,clock.date());var customers=db.queryForList("select id from customers where clinic_id=? and phone=? order by created_at limit 1",UUID.class,clinic,mobile);UUID customer=customers.isEmpty()?UUID.randomUUID():customers.getFirst();if(customers.isEmpty())db.update("insert into customers(id,clinic_id,branch_id,full_name,phone,age,free_cancellations_remaining) select ?,?,?,?,?,?,free_customer_cancellations from clinics where id=?",customer,clinic,branch,x.name().trim(),mobile,x.age(),clinic);else db.update("update customers set full_name=?,age=coalesce(?,age),active=true where id=? and clinic_id=?",x.name().trim(),x.age(),customer,clinic);UUID id=UUID.randomUUID(),tracking=UUID.randomUUID();try{db.update("insert into queue_entries(id,tracking_token,clinic_id,branch_id,customer_id,session_id,queue_date,token_number,queue_period,patient_name,mobile,age,weight_kg,bp,sugar,registered_by) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,tracking,clinic,branch,customer,session.id(),clock.date(),token,period,x.name().trim(),mobile,x.age(),x.weightKg(),x.bp(),x.sugar(),actor);}catch(DuplicateKeyException e){throw new QueueError(HttpStatus.CONFLICT,"This mobile number already has a token for the "+period.toLowerCase()+" session");}db.update("insert into patient_history_events(clinic_id,branch_id,customer_id,queue_entry_id,event_type,event_data,actor_user_id) values(?,?,?,?, 'QUEUE_REGISTERED',jsonb_build_object('token',?,'session',?,'weightKg',?,'bp',?,'sugar',?),?)",clinic,branch,customer,id,token,period,x.weightKg(),x.bp(),x.sugar(),actor);queueMessage(clinic,id,mobile,"TOKEN_CREATED","Your "+period.toLowerCase()+" queue token is "+token+". Please keep this page open for live updates.");return Map.of("id",id,"trackingToken",tracking,"tokenNumber",token,"queuePeriod",period,"status","WAITING");}
 @PostMapping("/queue/{id}/cancel") @Transactional public Map<String,Object> cancel(@AuthenticationPrincipal TenantPrincipal p,@PathVariable UUID id){tenant(p);int n=db.update("update queue_entries set status='CANCELLED' where id=? and clinic_id=? and branch_id=? and status='WAITING'",id,p.clinicId(),p.branchId());if(n==0)throw new QueueError(HttpStatus.CONFLICT,"Only a waiting patient can be cancelled");return Map.of("status","CANCELLED");}
 @PostMapping("/queue/pause") public Map<String,Object> pause(@AuthenticationPrincipal TenantPrincipal p){tenant(p);role(p,"PRACTITIONER","OWNER");Boolean paused=db.queryForObject("update branches set queue_paused=not queue_paused where id=? and clinic_id=? returning queue_paused",Boolean.class,p.branchId(),p.clinicId());return Map.of("paused",paused);}
 @PostMapping("/queue/next") @Transactional public Map<String,Object> next(@AuthenticationPrincipal TenantPrincipal p){tenant(p);role(p,"PRACTITIONER","OWNER");Boolean paused=db.queryForObject("select queue_paused from branches where id=? and clinic_id=? for update",Boolean.class,p.branchId(),p.clinicId());if(Boolean.TRUE.equals(paused))throw new QueueError(HttpStatus.CONFLICT,"Resume the queue before calling the next patient");db.update("update queue_entries set status='COMPLETED',completed_at=now() where clinic_id=? and branch_id=? and queue_date=current_date and status='IN_CONSULTATION'",p.clinicId(),p.branchId());var next=db.queryForList("select id,customer_id,token_number,patient_name,mobile from queue_entries where clinic_id=? and branch_id=? and queue_date=current_date and status='WAITING' order by token_number for update skip locked limit 1",p.clinicId(),p.branchId());if(next.isEmpty())throw new QueueError(HttpStatus.CONFLICT,"No patients are waiting");var row=next.getFirst();db.update("update queue_entries set status='IN_CONSULTATION',started_at=now() where id=?",row.get("id"));db.update("update branches set current_token=? where id=? and clinic_id=?",row.get("token_number"),p.branchId(),p.clinicId());db.update("insert into daily_queue_counters(clinic_id,branch_id,counter_date,current_token,last_issued_token) values(?,?,current_date,?,?) on conflict(branch_id,counter_date) do update set current_token=excluded.current_token,updated_at=now()",p.clinicId(),p.branchId(),row.get("token_number"),row.get("token_number"));db.update("insert into patient_history_events(clinic_id,branch_id,customer_id,queue_entry_id,event_type,event_data,actor_user_id) values(?,?,?,?, 'CONSULTATION_STARTED',jsonb_build_object('token',?),?)",p.clinicId(),p.branchId(),row.get("customer_id"),row.get("id"),row.get("token_number"),p.userId());var upcoming=db.queryForList("select id,mobile from queue_entries where clinic_id=? and branch_id=? and queue_date=current_date and status='WAITING' order by token_number limit 2",p.clinicId(),p.branchId());Integer avg=db.queryForObject("select average_visit_minutes from clinics where id=?",Integer.class,p.clinicId());for(int i=0;i<upcoming.size();i++){var u=upcoming.get(i);queueMessage(p.clinicId(),(UUID)u.get("id"),String.valueOf(u.get("mobile")),"QUEUE_REMINDER","You are "+(i+1)+" in the queue. Estimated wait: "+((i+1)*avg)+" minutes. Please be ready.");}return row;}
 private void queueMessage(UUID clinic,UUID entry,String recipient,String type,String body){var options=db.queryForList("select s.channel,s.enabled,s.sender_source,s.clinic_number,p.default_sms_number,p.default_whatsapp_number from clinics c join clinic_communication_settings s on s.clinic_id=c.id cross join platform_configuration p where c.id=? order by case when s.channel=c.reminder_channel then 0 else 1 end",clinic);for(var option:options){if(!Boolean.TRUE.equals(option.get("enabled")))continue;String channel=String.valueOf(option.get("channel"));Object sender="CLINIC_NUMBER".equals(option.get("sender_source"))?option.get("clinic_number"):("SMS".equals(channel)?option.get("default_sms_number"):option.get("default_whatsapp_number"));db.update("insert into message_outbox(clinic_id,queue_entry_id,channel,sender,recipient,message_type,body) values(?,?,?,?,?,?,?)",clinic,entry,channel,sender,recipient.replaceAll("[ -]",""),type,body);return;}}
 private record BranchClock(LocalDate date,LocalTime time){} private record SessionWindow(UUID id,String code,LocalTime startsAt,LocalTime endsAt){}
 private Map<String,Object> publicClinic(String identifier){String normalized=identifier.trim().toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");var rows=db.queryForList("select c.id clinic_id,b.id branch_id,c.name clinic_name,c.slug,c.theme,c.average_visit_minutes,c.logo_content_type,encode(c.logo_data,'base64') logo_base64,b.name branch_name from clinics c join branches b on b.clinic_id=c.id and b.active where c.active and c.public_checkin_enabled and (lower(c.slug)=? or lower(regexp_replace(c.name,'[^a-zA-Z0-9]+','-','g'))=?) order by b.name limit 1",normalized,normalized);if(rows.isEmpty())throw new QueueError(HttpStatus.NOT_FOUND,"Clinic check-in page not found");return rows.getFirst();}
 private BranchClock branchClock(UUID branch){String timezone=db.queryForObject("select timezone from branches where id=?",String.class,branch);ZonedDateTime now=ZonedDateTime.now(ZoneId.of(timezone==null?"Asia/Kolkata":timezone));return new BranchClock(now.toLocalDate(),now.toLocalTime());}
 private SessionWindow clinicSession(UUID clinic,UUID branch,LocalTime now){var sessions=db.query("select id,code,starts_at,ends_at from clinic_sessions where clinic_id=? and branch_id=? and active order by sort_order",(r,n)->new SessionWindow(r.getObject("id",UUID.class),r.getString("code"),r.getObject("starts_at",LocalTime.class),r.getObject("ends_at",LocalTime.class)),clinic,branch);for(SessionWindow s:sessions){boolean contains=s.startsAt().isBefore(s.endsAt())||s.startsAt().equals(s.endsAt())?(!now.isBefore(s.startsAt())&&now.isBefore(s.endsAt())):(!now.isBefore(s.startsAt())||now.isBefore(s.endsAt()));if(contains)return s;}throw new QueueError(HttpStatus.CONFLICT,"The clinic is not accepting registrations in the current session");}
 private String clientIp(HttpServletRequest request){String forwarded=request.getHeader("X-Forwarded-For");return forwarded==null||forwarded.isBlank()?request.getRemoteAddr():forwarded.split(",")[0].trim();}
 private void limitPublicRegistration(UUID clinic,String ip){if(publicAttempts.size()>10000)publicAttempts.clear();String key=sha256(clinic+"|"+ip);Instant cutoff=Instant.now().minus(Duration.ofMinutes(10));Deque<Instant> attempts=publicAttempts.computeIfAbsent(key,k->new ArrayDeque<>());synchronized(attempts){while(!attempts.isEmpty()&&attempts.peekFirst().isBefore(cutoff))attempts.removeFirst();if(attempts.size()>=8)throw new QueueError(HttpStatus.TOO_MANY_REQUESTS,"Too many registration attempts. Please wait 10 minutes or ask reception for help");attempts.addLast(Instant.now());}}
 private String sha256(String value){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(digest);}catch(Exception e){throw new IllegalStateException(e);}}
 private void tenant(TenantPrincipal p){if(p==null||p.clinicId()==null)throw new QueueError(HttpStatus.FORBIDDEN,"A clinic context is required");} private void role(TenantPrincipal p,String... roles){if(Arrays.stream(roles).noneMatch(p.role()::equals))throw new QueueError(HttpStatus.FORBIDDEN,"Doctor access required");}
 @ResponseStatus class QueueError extends RuntimeException{final HttpStatus status;QueueError(HttpStatus s,String m){super(m);status=s;}} @ExceptionHandler(QueueError.class) ResponseEntity<?> error(QueueError e){return ResponseEntity.status(e.status).body(Map.of("error",e.getMessage()));}
}
